package com.smartbank.service;
import com.smartbank.entity.*; import com.smartbank.repository.*; import org.springframework.http.HttpStatus; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.server.ResponseStatusException; import java.math.*; import java.util.*;
@Service public class BankingService {
 private final AccountRepository accounts; private final TransactionRepository transactions; private final UserRepository users; private final NotificationRepository notifications;
 public BankingService(AccountRepository a,TransactionRepository t,UserRepository u,NotificationRepository n){accounts=a;transactions=t;users=u;notifications=n;}
 public record AccountView(Long id,String accountNumber,String accountType,String status,BigDecimal balance){}
 public record TxView(String reference,String type,BigDecimal amount,String status,String description,java.time.Instant createdAt,String accountNumber){}
 public record NotificationView(Long id,String title,String message,boolean read,java.time.Instant createdAt){}
 private AccountView view(BankAccount a){return new AccountView(a.id,a.accountNumber,a.accountType,a.status,a.balance);}
 public List<AccountView> myAccounts(String email){User u=user(email);return accounts.findByUserIdOrderByIdAsc(u.id).stream().map(this::view).toList();}
 @Transactional(readOnly=true) public List<TxView> myTransactions(String email){User u=user(email);return accounts.findByUserIdOrderByIdAsc(u.id).stream().flatMap(a->transactions.findTop100ByAccountIdOrderByCreatedAtDesc(a.id).stream()).sorted(Comparator.comparing((BankTransaction t)->t.createdAt,Comparator.nullsLast(Comparator.reverseOrder()))).map(t->new TxView(t.reference,t.type,t.amount,t.status,t.description,t.createdAt,t.account.accountNumber)).toList();}
 public List<NotificationView> myNotifications(String email){User u=user(email);return notifications.findTop50ByUserIdOrderByCreatedAtDesc(u.id).stream().map(n->new NotificationView(n.id,n.title,n.message,n.read,n.createdAt)).toList();}
 @Transactional public void markNotificationRead(String email,Long id){User u=user(email);Notification n=notifications.findByIdAndUserId(id,u.id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Notification not found."));n.read=true;}
 public User user(String email){return users.findByEmailIgnoreCase(email).filter(x->x.active).orElseThrow(()->new ResponseStatusException(HttpStatus.UNAUTHORIZED,"User is not active."));}
 @Transactional public Map<String,Object> updateProfile(String email,String name,String phone){User u=user(email);u.fullName=name.trim();u.phone=phone.trim();Map<String,Object> m=new LinkedHashMap<>();m.put("id",u.id);m.put("name",u.fullName);m.put("email",u.email);m.put("phone",u.phone);m.put("role",u.role);return m;}
 private BankAccount owned(String email,Long id){BankAccount a=accounts.findLockedById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Account not found."));if(a.user==null||a.user.email==null||!a.user.email.equalsIgnoreCase(email))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"You cannot access this account.");if(!a.status.equals("ACTIVE"))throw new ResponseStatusException(HttpStatus.CONFLICT,"Account is not active.");return a;}
 private void reference(BankTransaction t){t.reference="SB"+UUID.randomUUID().toString().replace("-","").substring(0,16).toUpperCase();}
 private BigDecimal amount(BigDecimal x){if(x==null||x.scale()>2||x.compareTo(BigDecimal.ZERO)<=0||x.compareTo(new BigDecimal("1000000"))>0)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Amount must be positive, up to 2 decimal places, and no more than 1,000,000.");return x.setScale(2);}
 @Transactional public AccountView deposit(String email,Long id,BigDecimal value,String note){var a=owned(email,id);var n=amount(value);a.balance=a.balance.add(n);saveTx(a,null,"DEPOSIT",n,note);return view(a);}
 @Transactional public AccountView withdraw(String email,Long id,BigDecimal value,String note){var a=owned(email,id);var n=amount(value);if(a.balance.compareTo(n)<0)throw new ResponseStatusException(HttpStatus.CONFLICT,"Insufficient funds.");a.balance=a.balance.subtract(n);saveTx(a,null,"WITHDRAWAL",n,note);return view(a);}
 @Transactional public AccountView transfer(String email,Long id,String recipient,BigDecimal value,String note){var a=owned(email,id);var n=amount(value);BankAccount b=accounts.findLockedByNumber(recipient).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Recipient account not found."));if(a.id.equals(b.id))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Self transfers are not allowed.");if(!b.status.equals("ACTIVE")||!b.user.active)throw new ResponseStatusException(HttpStatus.CONFLICT,"Recipient account is not active.");if(a.balance.compareTo(n)<0)throw new ResponseStatusException(HttpStatus.CONFLICT,"Insufficient funds.");a.balance=a.balance.subtract(n);b.balance=b.balance.add(n);saveTx(a,b,"TRANSFER_OUT",n,note);saveTx(b,a,"TRANSFER_IN",n,"Transfer from account ••••"+a.accountNumber.substring(Math.max(0,a.accountNumber.length()-4)));return view(a);}
 private void saveTx(BankAccount a,BankAccount b,String type,BigDecimal n,String note){BankTransaction t=new BankTransaction();reference(t);t.type=type;t.amount=n;t.status="COMPLETED";t.description=note;t.account=a;t.relatedAccount=b;transactions.save(t);Notification notification=new Notification();notification.user=a.user;notification.title=switch(type){case "DEPOSIT"->"Deposit received";case "WITHDRAWAL"->"Withdrawal completed";case "TRANSFER_OUT"->"Transfer sent";default->"Transfer received";};notification.message=(note==null||note.isBlank()?type.replace('_',' '):note)+" · "+n.toPlainString();notifications.save(notification);}
 @Transactional public void register(User user){users.save(user);BankAccount a=new BankAccount();a.user=user;a.accountType="SAVINGS";a.accountNumber="SB"+String.format("%010d",new java.security.SecureRandom().nextInt(1_000_000_000));a.balance=BigDecimal.ZERO;accounts.save(a);}
 public List<Map<String,Object>> adminUsers(){return users.findAllByRoleOrderByIdDesc("CUSTOMER").stream().map(u->{Map<String,Object> m=new LinkedHashMap<>();m.put("id",u.id);m.put("name",u.fullName);m.put("email",u.email);m.put("phone",u.phone);m.put("role",u.role);m.put("active",u.active);m.put("accounts",accounts.findByUserIdOrderByIdAsc(u.id).stream().map(this::view).toList());return m;}).toList();}
 public Map<String,Object> adminStats(){Map<String,Object> m=new LinkedHashMap<>();m.put("customers",users.countByRole("CUSTOMER"));m.put("accounts",accounts.count());m.put("activeAccounts",accounts.countByStatus("ACTIVE"));m.put("transactions",transactions.count());m.put("totalBalance",accounts.findAll().stream().map(a->a.balance).reduce(BigDecimal.ZERO,BigDecimal::add));return m;}
 @Transactional public void setActive(Long id,boolean active){User u=users.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Customer not found."));if(u.role.equals("ADMIN"))throw new ResponseStatusException(HttpStatus.CONFLICT,"Administrator accounts cannot be changed here.");u.active=active;}
 @Transactional(readOnly=true) public List<TxView> allTransactions(){return transactions.findTop100ByOrderByCreatedAtDesc().stream().map(t->new TxView(t.reference,t.type,t.amount,t.status,t.description,t.createdAt,t.account.accountNumber)).toList();}
}
